<div class="toolbar"><p class="text-secondary mb-0"><?= e($result['total']) ?> pedidos · ventas y distribución</p><div class="toolbar-actions"><a class="btn btn-outline-secondary" href="<?= e(url('orders-export',array_intersect_key($_GET,array_flip(['q','from','to'])))) ?>">↓ Exportar CSV</a><?php if(can_write()): ?><a class="btn btn-primary" href="<?= e(url('order-form')) ?>">+ Nuevo pedido</a><?php endif ?></div></div><section class="panel"><form class="filter-bar" method="get"><input type="hidden" name="r" value="orders"><div><label for="q" class="form-label small">Pedido o cliente</label><input id="q" name="q" class="form-control" value="<?= e($_GET['q']??'') ?>" placeholder="Buscar…"></div><?php foreach(['from'=>'Desde','to'=>'Hasta'] as $k=>$label): ?><div><label class="form-label small" for="<?= $k ?>"><?= $label ?></label><input type="date" id="<?= $k ?>" class="form-control" name="<?= $k ?>" value="<?= e($_GET[$k]??'') ?>"></div><?php endforeach ?><button class="btn btn-primary align-self-end">Filtrar</button><a class="btn btn-light align-self-end" href="<?= e(url('orders')) ?>">Limpiar</a></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>País de envío</th><th>Venta neta</th><th>Acciones</th></tr></thead><tbody><?php foreach($result['rows'] as $r): ?><tr><td><strong>#<?= e($r['OrderID']) ?></strong></td><td><?= e($r['CompanyName']) ?></td><td><?= e(substr($r['OrderDate']??'',0,10)) ?></td><td><?= e($r['ShipCountry']) ?></td><td><?= money($r['Total']) ?></td><td><a class="btn btn-sm btn-light" href="<?= e(url('order-show',['id'=>$r['OrderID']])) ?>">Ver detalle</a></td></tr><?php endforeach ?><?php if(!$result['rows']): ?><tr><td colspan="6" class="empty-state">No hay pedidos para estos filtros.</td></tr><?php endif ?></tbody></table></div><?php $paginationRoute='orders';$paginationParams=array_intersect_key($_GET,array_flip(['q','from','to']));require ROOT.'/app/Views/partials/pagination.php'; ?></section>
